import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function daysAgo(days: number): Date {
  const date = new Date();
  date.setDate(date.getDate() - days);
  return startOfDay(date);
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date | null>(startOfDay(new Date()));

  const presets = [
    { label: 'Сегодня', value: daysAgo(0) },
    { label: 'Вчера', value: daysAgo(1) },
    { label: 'Неделя назад', value: daysAgo(7) },
  ];

  const applyDate = (date: Date | null) => {
    setSelected(date);
    onChange?.(date);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        padding: '16px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
      }}
    >
      <div
        style={{
          fontFamily: 'var(--jx-font-sans)',
          fontSize: '13px',
          color: 'var(--jx-text-2)',
        }}
      >
        Дата отчёта
      </div>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.label}
            active={isSameDay(selected, preset.value)}
            onClick={() => applyDate(preset.value)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selected} onValueChange={applyDate} />
    </div>
  );
}

